/* Event main quest. All durable progress comes from the authenticated service. */
(()=>{'use strict';
if(window.CAMPUS_SEASON!=='pepero')return;
const $=id=>document.getElementById(id),viewport=$('viewport');if(!viewport)return;
let state=null,busy=false,room=0,roomTicket=null,activePlay=null,lastRefresh=0,nearStation=null,autoCooldown=0;
const practiceCompleted=new Set();let missionRenderer=null,missionMap=null,missionOpening=false,exteriorBlocked=true;let walkGoal=null;const held=new Set(),actor={x:450,y:555,moving:false,dir:'up',avatar:'male-1'};
const makeDialog=(id,title,cls='')=>{const d=document.createElement('dialog');d.id=id;d.className='mq-dialog '+cls;d.innerHTML=`<header><div><div class="mq-caption">11.11 · CHOCOLATE MYSTERY</div><h2>${title}</h2></div><button type="button" class="mq-close" aria-label="닫기">×</button></header><div class="mq-body"></div>`;document.body.append(d);d.querySelector('.mq-close').onclick=()=>d.close();d.addEventListener('keydown',e=>e.stopPropagation());return d;};
const dialog=makeDialog('mainQuestDialog','사라진 11번째 빼빼로'),interior=makeDialog('mainQuestRoom','ROOM','mq-room'),gameDialog=makeDialog('mainQuestGame','MISSION','mq-game');
interior.querySelector('.mq-body').innerHTML='<canvas id="mainQuestCanvas" tabindex="0" aria-label="미션 공간. 방향키 또는 이동 키로 이동하고 상호작용 키를 누르세요"></canvas><div class="mq-room-foot"><span id="mainQuestRoomHint">미션 오브젝트 가까이 이동하세요</span><button id="mainQuestInteract" type="button">상호작용</button><button id="mainQuestExit" type="button">포탈로 나가기</button></div>';
const practiceLabel=document.createElement('label');practiceLabel.className='mq-practice';practiceLabel.hidden=true;practiceLabel.innerHTML='<input type="checkbox"> 연습 모드 · 메인 진행 반영 안 함';interior.querySelector('.mq-room-foot').append(practiceLabel);
const canvas=$('mainQuestCanvas'),g=canvas.getContext('2d');
const roomSteps=document.createElement('div');roomSteps.className='mq-room-journey';roomSteps.innerHTML='<span class="mq-room-mode"></span><ol></ol><span class="mq-room-count"></span>';interior.querySelector('.mq-body').insertBefore(roomSteps,canvas);
const roomNext=document.createElement('div');roomNext.className='mq-room-next';interior.querySelector('.mq-body').insertBefore(roomNext,canvas);
canvas.addEventListener('pointerdown',()=>canvas.focus());
const tracker=document.createElement('details');tracker.className='mq-tracker';tracker.open=true;tracker.innerHTML='<summary>사라진 11번째 빼빼로</summary><ol></ol><button type="button">현재 미션 안내</button>';viewport.append(tracker);
const ranks=document.createElement('details');ranks.className='mq-ranking';ranks.innerHTML='<summary>이벤트 랭킹 · 메인 미션</summary><div class="mq-rank-body"><strong class="mq-my-rank">내 순위 · 아직 완료 전</strong><ol></ol><button type="button">전체 랭킹 보기</button><p>현재 기록은 실시간 순위이며 당첨 확정은 아닙니다.</p></div>';viewport.append(ranks);new ResizeObserver(()=>tracker.style.top=(ranks.offsetTop+ranks.offsetHeight+10)+'px').observe(ranks);ranks.querySelector('button').onclick=()=>run(()=>showRanking(1));
async function showRanking(page){const data=await api(null,'ranking/?page='+page);info('메인 미션 전체 랭킹','내 순위: '+(data.myRank||'완료 전')+'\n\n'+(data.entries.map(e=>e.rank+'위 · '+e.nickname).join('\n')||'아직 최종 전달을 마친 참여자가 없습니다.'),[...(page>1?[['이전',()=>showRanking(page-1)]]:[]),...(data.hasMore?[['다음',()=>showRanking(page+1)]]:[])]);}
tracker.querySelector('button').onclick=()=>run(async()=>{await refresh();info('현재 미션',guidance());});
const arrow=document.createElement('div');arrow.className='mq-arrow';arrow.setAttribute('aria-hidden','true');arrow.innerHTML='<span class="mq-arrow-tag">MAIN QUEST</span><span class="mq-arrow-label"></span><svg class="mq-arrow-mark" width="38" height="50" viewBox="0 0 38 50"><path d="M19 1 24 9 19 17 14 9Z" fill="#fff3b6" stroke="#97582d" stroke-width="2"/><path d="M7 18H31V28H37L19 48 1 28H7Z" fill="#ffd56b" stroke="#7b4127" stroke-width="2" stroke-linejoin="round"/><path d="M10 21H28V25H10Z" fill="#fff6c4"/><path d="M9 32 19 42 29 32" fill="none" stroke="#e49b35" stroke-width="4"/></svg>';viewport.append(arrow);
const portals=window.CampusMissionRooms.spec.entrances;
for(const p of portals){const b=document.createElement('div');b.className='mq-portal mq-entry-prompt';b.dataset.room=p.room;b.innerHTML='<strong></strong>';viewport.append(b);p.button=b;}
document.addEventListener('keydown',e=>{const k=window.CampusKeyboard?.key(e)||e.key.toLowerCase();if(k!=='e'||e.repeat||room||busy||exteriorBlocked||e.target.closest?.('input,textarea,select,[contenteditable="true"]'))return;const app=window.CampusApp,p=portals.find(p=>p.floor===app?.floor&&Math.hypot(app.player.x-p.x,app.player.y-p.y)<=70);if(p){e.preventDefault();e.stopImmediatePropagation();run(()=>enterRoom(p.room));}},true);
const guideObject=window.CampusWorlds.campus.objects.find(o=>o.id==='campus-guide-kkuwang');const mainGuide={floor:'campus',x:guideObject.x+guideObject.w/2,y:guideObject.y+guideObject.h/2,name:'18층 꾸왕이'};
function stop(){held.clear();const app=window.CampusApp;app?.presence.setInput([]);app?.poke?.setHeld(false);if(app)app.player.moving=false;window.dispatchEvent(new Event('campus:guide-open'));}
async function api(data,readPath,base='/api/event-main/'){const token=decodeURIComponent(document.cookie.split('; ').find(x=>x.startsWith('campus_csrftoken='))?.split('=').slice(1).join('=')||'');const r=await fetch(base+(readPath||(data?'action/':'status/')),{method:data?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:data?{'Content-Type':'application/json','X-CSRFToken':token}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(15000)});const j=await r.json();if(!r.ok){const error=new Error(j.message||'서버 기록을 확인하지 못했습니다.');error.code=j.error;throw error;}return j;}
async function refresh(){state=await api();lastRefresh=Date.now();renderTracker();return state;}
async function act(action,data={}){const r=await api({action,...data});state=r.state;renderTracker();return r;}
async function ticket(target){return(await window.CampusApp.presence.command('story_access',{target})).ticket;}
async function run(fn){if(busy||window.CampusFreeze?.blocking)return;busy=true;try{await fn();}catch(e){const node=document.createElement('p');node.className='mq-error';node.setAttribute('role','alert');node.textContent=e.message;if(dialog.open)dialog.querySelector('.mq-body').append(node);else if(interior.open||gameDialog.open)info('미션을 열 수 없어요',e.message);else window.CampusApp?.toast(e.message);}finally{busy=false;}}
function btn(text,fn,disabled=false){const b=document.createElement('button');b.type='button';b.textContent=text;b.disabled=disabled;b.onclick=()=>run(fn);return b;}
function info(title,copy,actions=[]){window.CampusQuestDialogue.clear(dialog);stop();dialog.querySelector('h2').textContent=title;const body=dialog.querySelector('.mq-body');body.replaceChildren();const p=document.createElement('p');p.textContent=copy;body.append(p);const row=document.createElement('div');row.className='mq-actions';row.append(...actions.map(a=>btn(...a)),btn('닫기',()=>dialog.close()));body.append(row);if(!dialog.open)dialog.showModal();}
function story(title,chapter,lines,actions=[],setting='campus'){stop();window.CampusQuestDialogue.show(dialog,{title,chapter,setting,lines,actions:actions.map(([label,fn])=>[label,()=>run(fn)])});}
const kline=(text,extra={})=>({speaker:'탐정 꾸왕이',role:'오늘의 사건 의뢰인',text,...extra});
const mline=text=>({speaker:'영석 매니저님',role:'ROOM 01 · 증거 분석 담당',person:'manager',text});
const pline=text=>({speaker:'나',role:'사라진 선물을 찾는 탐정',person:'player',text});
async function recipeNote(replay=false){
const saved=await api(null,'recipe/status/','/api/event-story/');
if(saved.hasNote&&!replay){recipeHolding();return;}
if(dialog.open)dialog.close();
stop();if(window.CampusRecipeDiscovery&&!await window.CampusRecipeDiscovery.play())return;
recipeScene('화단 사이에 숨은 쪽지','SECRET RECIPE · 발견',[
{...pline('어? 이게 뭐지? 반짝이던 곳에 이런 쪽지가 있었네.'),role:'뜻밖의 발견'},
{...pline('비밀 레시피…? 「특별한 빼빼로 한 개를 만드는 법」이라고 적혀 있어. 초콜릿 발도장도 찍혀 있고… 꾸왕이한테 가져가 봐야겠다.'),role:'쪽지의 주인은 누구일까?'}
],[[saved.hasNote?'다시 보기 마치기':'접힌 쪽지를 챙긴다',async()=>{
if(saved.hasNote){dialog.close();return;}
try{await api({action:'acquire',ticket:await ticket('recipe-note')},'recipe/action/','/api/event-story/');}
catch(error){
if(error.code!=='main_quest_required')throw error;
recipeScene('화단 사이에 숨은 쪽지','SECRET RECIPE · 발견',[recipeItem('메인 미션을 완료해야 주울 수 있을 것 같습니다.','아직 남아 있는 사건')],[['확인',()=>dialog.close()]]);return;
}
recipeScene('아이템 획득','SECRET RECIPE · 획득',[
{...pline('쪽지를 챙겼다. 재료는 두 사람 분량인데, 마지막 문장은 초콜릿 자국에 가려져 있네. 꾸왕이는 무슨 뜻인지 알겠지?'),role:'비밀 레시피 획득'},
{...pline('18층 게시판 앞에 있는 꾸왕이에게 물어보자.'),role:'꾸왕이에게 가져가기'}
],[['꾸왕이에게 가져간다',()=>{dialog.close();window.CampusApp?.toast?.('18층 게시판 앞 꾸왕이에게 레시피 쪽지를 보여 주세요.');}],['아직은 더 둘러본다',recipeHolding]]);
}],...(saved.hasNote?[['쪽지 보관 상태로 돌아가기',recipeHolding]]:[['일단 그대로 둔다',()=>recipeScene('나중에 다시 조사 가능','SECRET RECIPE · 발견',[recipeItem('누군가 잃어버린 레시피일지도 모른다. 쪽지를 잎 아래에 그대로 두었다. 다시 조사할 수 있도록 금빛이 반짝이던 위치를 기억해 두자.','발견한 위치 기억하기')],[['확인',()=>dialog.close()]])]])]);
}
function recipeItem(text,role='숨겨진 레시피'){return {...pline(text),person:'item',art:'assets/seasonal/pepero/secret-recipe-pixel-v1.webp',role};}
function recipeScene(title,chapter,lines,actions){story(title,chapter,lines,actions,'rooftop');}
function recipeHolding(){recipeScene('쪽지 보관 중','SECRET RECIPE · 보관',[recipeItem('쪽지를 잘 접어 챙겼다. 금빛 아래에서 찾은 이 레시피를 18층 게시판 앞의 꾸왕이에게 보여 주자.','초콜릿 묻은 레시피 쪽지')],[['발견 연출 다시 보기',()=>recipeNote(true)],['확인',()=>dialog.close()]]);}
async function recipeAct(action,proof,extra={}){
const result=await api({action,ticket:proof,...extra},'recipe/action/','/api/event-story/');
if(Array.isArray(result.achievements))window.dispatchEvent(new CustomEvent('campus:achievements',{detail:result.achievements}));
if(result.newly_completed?.length)window.dispatchEvent(new CustomEvent('campus:achievement-earned',{detail:result}));
return result;
}
async function recipeGuide(){
let saved=await api(null,'recipe/status/','/api/event-story/');
if(!saved.hasNote){story('안내가이드 꾸왕이','SECRET RECIPE · 일반 대화',[kline('캠퍼스는 잘 둘러보고 있어? 막히는 일이 있으면 나한테 물어봐. 작은 단서도 그냥 지나치지 말고!',{role:'캠퍼스 안내'})],[['확인',()=>dialog.close()]]);return;}
if(saved.secretCompleted){recipeDialogue('repeat',saved);return;}
const proof=await ticket('recipe-guide');saved=(await recipeAct('recognize',proof)).state;
recipeDialogue(saved.secretCompleted?'repeat':saved.topping|| (saved.secretStarted?'share':saved.deferred?'invitation':'recognize'),saved,proof);
}
function recipeDialogue(scene,saved,proof){
const next=key=>()=>recipeDialogue(key,saved,proof);
const advance=(action,key,extra={})=>async()=>{const result=await recipeAct(action,proof,extra);recipeDialogue(result.state.secretCompleted?'repeat':key,result.state,proof);};
const screens={
recognize:['아이템 전용 대화',[
 pline('옥상에서 반짝이는 곳을 조사하다가 이걸 찾았어. 비밀 레시피라는데… 이 발도장, 꾸왕이 네 거 아니야?'),
 kline('어… 그 쪽지! 화단 깊숙이 숨겨 둔 건데… 어떻게 찾아냈어?',{role:'쪽지를 알아본 꾸왕이'}),
 kline('초콜릿 발도장까지 그대로네. 맞아, 내가 쓰던 레시피야. 다른 사람한테는 보여 준 적 없는데…',{role:'쪽지를 알아본 꾸왕이'})
],[['이야기를 듣는다',next('confess')]]],
confess:['숨겨진 이야기',[kline('사실 몰래 연습하던 레시피야. 누군가에게 고맙다고 말하려고 특별한 한 개를 만들고 싶었거든. 그런데 자꾸 실패해서… 남에게 보이기 부끄러워 화단의 잎 아래에 쪽지를 숨겨 버렸어.',{emotion:'shy'})],[['한 개인데 재료는 왜 두 사람 분량이야?',next('whyTwo')],['누구에게 주려고 했는데?',next('recipient')]]],
recipient:['선택 대사 · 마음',[kline('매번 내 이야기를 끝까지 들어주는 사람에게. ...지금도 이렇게 내 앞에 서서 들어주고 있잖아.',{emotion:'shy'})],[['이야기를 계속 듣는다',next('whyTwo')]]],
whyTwo:['레시피의 빈칸',[kline('그게 이 레시피의 비밀이야. 제일 아래 문장은... 「마지막 한 개는, 혼자 만들지 않기.」\n완벽하게 만들려다 그 문장을 잊고 있었어.')],[['이야기를 계속 듣는다',next('invitation')]]],
invitation:['루트 선택',[kline('쪽지를 돌려줘서 고마워. 이번에는 숨기지 않을게.\n혹시 괜찮다면... 마지막 한 개를 나랑 같이 완성해 줄래?')],[['좋아. 이번에는 같이 만들자.',advance('start','share')],['지금은 하던 일부터 마저 할게.',advance('defer','defer')]]],
defer:['일반 동선으로 복귀',[kline('응, 급하게 정할 필요는 없어. 쪽지는 네가 잠깐 맡아 줘. 마음이 생기면 다시 말을 걸어 줘. 함께 만들 자리는 비워 둘게.')],[['확인',()=>dialog.close()]]],
share:['함께 완성하기',[kline('그럼 역할을 나누자! 나는 초콜릿을 입힐게. 너는 마지막 토핑을 부탁해. 이제 실패해도 괜찮아. 어느 부분을 같이 고치면 되는지 알잖아.',{emotion:'happy'})],[['마지막 토핑을 고른다',next('finishChoice')]]],
finishChoice:['마지막 토핑',[kline('마지막 한 칸을 비워 뒀어. 어떤 마음으로 완성하고 싶어?')],[['고마워. 네 이야기를 들려줘서.',advance('topping','thanks',{topping:'thanks'})],['다음에도 같이 만들자.',advance('topping','promise',{topping:'promise'})]]],
thanks:['히든 대사 · 고마움',[kline('나도 고마워. 잃어버린 건 쪽지인 줄 알았는데... 다시 만들 용기를 찾아줬네. 이 한 개에는 고맙다는 말을 두 사람 몫으로 담자.',{emotion:'happy'})],[['레시피를 함께 완성한다',next('secretEnd')]]],
promise:['히든 대사 · 약속',[kline('약속이야! 다음에는 쪽지를 숨기는 대신 네 이름부터 적어 둘게. 이 한 개는 완성이고, 다음 한 개는 우리 약속이야.',{emotion:'happy'})],[['레시피를 함께 완성한다',next('secretEnd')]]],
secretEnd:['둘이 쓴 레시피',[pline('레시피 맨 아래, 작은 발도장 옆에 네 표시를 남겼다. 「마지막 한 개는, 함께 만든 사람에게.」')],[['레시피 완성',async()=>{await recipeAct('finish',proof);dialog.close();}]]],
repeat:['완료 후 다시 대화',[kline('우리 레시피는 잘 보관하고 있어. 이번에는 숨겨 놓지 않았어! 너랑 같이 만든 거라고 당당하게 말할 수 있으니까.',{emotion:'happy'})],[['확인',()=>dialog.close()]]]
};
const [title,lines,actions]=screens[scene];story(title,'SECRET RECIPE · '+title,lines,actions);
}
function workshopStory(code,action){const scripts={card_match:['재료부터 확인해 볼까? 어질러진 재료 카드에서 같은 짝을 찾아야 해.','스틱과 초콜릿을 빠짐없이 준비하면, 다음은 초콜릿 코팅이야.'],coating:['이번에는 과자 대부분을 초콜릿으로 덮어 볼 거야. 끝부분은 손잡이로 조금 남겨 두자.','초콜릿 끝이 완벽선에 닿는 순간 멈춰 줘! 세 번 모두 표시된 성공 구간 안에서 멈춰 줘. 완벽선 기준 평균 오차도 200ms 이내여야 해.'],topping:['이번 주문은 딸기 10개, 아몬드 10개! 초콜릿이 굳기 전에 30초 안에 골라 받아 줘.','탄 초콜릿은 피해 줘! 받을 때마다 빼빼로가 짧아지고, 세 번 받으면 다시 만들어야 해. 일반 토핑은 더 받아도 괜찮고, 필요한 토핑을 연속으로 받으면 콤보가 이어져.'],wrapping:['재료 준비, 코팅, 데코까지 모두 끝났어. 이제 마지막 포장이야.','포장 애니메이션을 끝까지 확인한 다음, 완성한 선물을 18층의 나에게 가져와 줘!']};story('한 개의 선물을 만드는 일','CHAPTER 04 · CHOCOLATE ATELIER',scripts[code].map(t=>kline(t,{role:'꾸왕이가 남긴 제작 안내'})),[['작업 시작',()=>{dialog.close();return action();}]],'workshop');}
function guidance(){if(!state)return '진행 기록을 불러오는 중';return ['18층 꾸왕이에게 말을 걸어 사건의 단서를 확인하세요.','옥상 ROOM 01에서 영석 매니저님과 대화 → 서브쿼리 메모리 게임 → 매니저님에게 수량표를 제출하세요.','18층 꾸왕이에게 돌아가 10초 빼빼로 타격 챌린지를 마치세요.','옥상 ROOM 02에서 카드 뒤집기 → 초콜릿 코팅 → 토핑 뿌리기 → 포장을 진행하세요.','18층 꾸왕이에게 제작한 선물을 전달하세요.','사건 해결 완료'][state.stage-1];}
function renderTracker(){const rk=state.ranking||{myRank:null,top3:[]};ranks.querySelector('.mq-my-rank').textContent='내 순위 · '+(rk.myRank?rk.myRank+'위':'아직 완료 전');ranks.querySelector('ol').replaceChildren(...rk.top3.map(e=>{const li=document.createElement('li');li.textContent=e.rank+'위 · '+e.nickname;return li;}));tracker.querySelector('ol').replaceChildren(...state.steps.map((s,i)=>{const li=document.createElement('li');li.textContent=(s.complete?'✓ ':`${String(i+1).padStart(2,'0')} `)+s.name;li.className=s.complete?'done':state.stage===i+1?'current':'';return li;}));tracker.querySelector('summary').textContent='사라진 11번째 빼빼로'+(state.window.preview?' · 미리보기':'');}
async function investigate(){await refresh();const t=await ticket('investigate');story('사라진 11번째 빼빼로','CHAPTER 01 · A MISSING GIFT',[
kline('잠깐! 혹시 나 좀 도와줄 수 있어? 행사에 나눠 줄 빼빼로 선물이 하나 모자라!'),pline('하나가 사라졌다고? 수량을 잘못 센 건 아닐까?'),kline('그래서 수량표를 가져왔어. 그런데 기록이 세 장이나 있어서… 어느 걸 믿어야 할지 모르겠어.',{evidence:'기록   참가자   선물\n A       11       11\n B       10       10\n C       10       11'}),kline('수량표를 들고 옥상 ROOM 01의 영석 매니저님을 찾아가 줘. 매니저님과 기록의 순서를 분석하면 단서를 찾을 수 있을 거야!')],[['단서 확인 · 조사 시작',async()=>{const r=await act('investigate',{ticket:t});story(r.first?'조사를 시작합니다':'진행 중인 조사','CHAPTER 02 · FOLLOW THE CLUE',[kline(r.first?'고마워! 옥상 ROOM 01로 가서 영석 매니저님께 먼저 말을 걸어 줘. 설명을 듣고 SQL 기억 분석기에서 기록의 순서를 복원해 보자!':guidance())],[['조사하러 가기',()=>dialog.close()]]);}]]);}
async function confession(){await refresh();const t=await ticket('roof-guide');if(state.stage<3){story('아직 남은 단서','MAIN QUEST',[kline('먼저 수량표를 조사하고 ROOM 01에서 진실을 알아내 줘!')]);return;}story('꾸왕이의 고백','CHAPTER 03 · THE TRUTH',[
pline('C는 최종 기록이 아니었어. 참가자가 한 명 더 들어와서, 마지막 수량표 A에는 여분이 없었대.'),kline('그, 그랬구나… 사실 C에 하나가 남는다고 적혀 있어서… 내가 먹었어.',{emotion:'shy'}),pline('선물이 사라진 이유가 그거였구나!'),kline('내가 최종 수량도 확인하지 않고 먹어 버렸으니, 내 잘못이야. 이번에는 변명하지 않을게…',{emotion:'shy'}),kline('내가 머리를 두 손으로 감싸고 반성할게. 클릭하거나 찌르기 키를 누르면 빼빼로가 위에서 톡! 내려와서 부서질 거야.',{emotion:'shy',art:'assets/kkuwang-cover-head-v1.webp'}),pline('좋아. 10초 동안 반성하고 나면, 부족한 선물 한 개를 다시 만들자.'),kline('고마워. 횟수에 상관없이 10초를 끝까지 마치면 돼. 끝나면 옥상 ROOM 02에서 새 선물을 만들어 줘!')],[['꾸왕이 빼빼로 타격 챌린지',()=>{dialog.close();return startTouch(t);}]]);}
function stationList(){return (missionMap?.objects||[]).filter(o=>o.code);}
async function enterRoom(n){await refresh();stop();await window.CampusMissionRooms.ready;await window.CampusApp.presence.command('mission_room_enter',{room:n});}
async function exitRoom(){held.clear();window.CampusApp.presence.setInput([]);await window.CampusApp.presence.command('mission_room_exit',{});}
function syncRoomInventory(){const remaining=window.CampusApp?.player.peperoRemaining;actor.peperoRemaining=Number.isInteger(remaining)?Math.max(0,Math.min(10,remaining)):0;}
function applyMissionState(v){
if(!v){if(room){room=0;held.clear();missionMap=null;missionRenderer=null;if(gameDialog.open)gameDialog.close();if(dialog.open)dialog.close();if(interior.open)interior.close();}return;}
const n=Number(v.subject.slice(7)),opening=room!==n;room=n;
if(opening){missionMap=window.CampusMissionRooms.create(n);missionRenderer=window.CampusIsometric.create({data:missionMap});Object.assign(actor,v.actor,{avatar:window.CampusApp?.player.avatar||'male-1',walkTime:0});practiceLabel.hidden=!state?.canPractice;interior.querySelector('h2').textContent=missionMap.name;if(!interior.open)interior.showModal();canvas.focus();}
actor.targetX=v.actor.x;actor.targetY=v.actor.y;Object.assign(actor,{dir:v.actor.dir,moving:v.actor.moving,running:v.actor.running});syncRoomInventory();nearStation=v.nearby||null;
}
interior.querySelector('.mq-close').onclick=()=>run(exitRoom);interior.addEventListener('cancel',e=>{e.preventDefault();run(exitRoom);});
interior.addEventListener('close',()=>held.clear());$('mainQuestExit').textContent='옥상으로 나가기';$('mainQuestExit').onclick=()=>run(exitRoom);$('mainQuestInteract').onclick=()=>nearStation&&run(()=>activateStation());
let roomPokePending=false,lastRoomPoke=-Infinity;
async function pokeRoom(){
 if(room!==1||dialog.open||gameDialog.open||window.CampusFreeze?.blocking||roomPokePending||performance.now()-lastRoomPoke<280)return;
 roomPokePending=true;lastRoomPoke=performance.now();
 try{await window.CampusApp.presence.command('poke',{context:'classroom',subject:'mission1'});actor._campusPoke={started:performance.now(),dir:actor.dir,reach:48};}
 finally{roomPokePending=false;}
}
const roomPokeButton=document.createElement('button');roomPokeButton.id='mainQuestPoke';roomPokeButton.textContent='Z · 매니저 찌르기';roomPokeButton.onclick=()=>pokeRoom().catch(error=>window.CampusApp.toast(error.message));$('mainQuestInteract').after(roomPokeButton);
async function activateStation(){held.clear();window.CampusApp.presence.setInput([]);const result=await window.CampusApp.presence.command('interact',{});if(result.type!=='mission_station')return;const s=stationList().find(s=>s.code===result.code);if(!s)return;roomTicket=await ticket('room'+room);await interactStation(s);}
interior.addEventListener('keydown',e=>{if(gameDialog.open||dialog.open||window.CampusFreeze?.blocking)return;const k=window.CampusKeyboard?.key(e)||e.key.toLowerCase();if(k==='z'&&room===1){e.preventDefault();e.stopPropagation();held.add(k);return;}if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','shift','e'].includes(k)){e.preventDefault();if(k==='e'){if(!e.repeat)run(()=>activateStation());}else held.add(k);}});interior.addEventListener('keyup',e=>held.delete(window.CampusKeyboard?.key(e)||e.key.toLowerCase()));window.addEventListener('blur',()=>{held.clear();window.CampusApp?.presence.setInput([]);});
function managerConversation(){const canAnswer=state.games.sql_memory;story('수량표가 숨긴 진실','CHAPTER 02 · EVIDENCE LAB',canAnswer?[mline('기억 분석을 마쳤군요! 복원한 SQL 순서를 이용해서 수량표를 확인해 봅시다.')]:state.room1Briefed?[mline('왼쪽 SQL 기억 분석기에서 서브쿼리 메모리 게임에 도전해 보세요. 통과하면 저에게 돌아오면 됩니다.')]:[mline('안녕하세요. ROOM 01의 증거 분석을 맡은 영석 매니저입니다.'),pline('꾸왕이가 가져온 수량표가 서로 달라요. 정말 남는 선물이 있었을까요?'),mline('기록은 내용만큼 순서도 중요하죠. 먼저 왼쪽 분석기에서 SQL 실행 순서를 복원해 주세요.'),mline('서브쿼리 메모리 게임을 통과한 뒤 돌아오세요. 어느 기록에 여분이 있었는지 함께 분석해 봅시다.')],canAnswer?[['수량표 함께 분석하기',()=>managerAnswer()]]:[['설명 확인 · 게임 준비',async()=>{await act('room1_briefing',{ticket:roomTicket});dialog.close();}]],'analysis');}
function managerAnswer(){story('여분의 선물은 어디에?','CHAPTER 02 · ANALYZE THE RECORD',[
{...mline('선물 수에서 참가자 수를 빼면 여분을 알 수 있습니다. 여분이 정확히 한 개인 수량표를 골라 보세요.'),evidence:'gift_inventory\n기록   참가자   선물\n A       11       11\n B       10       10\n C       10       11\n\nSELECT record_name, gifts - participants AS spare\nFROM gift_inventory ORDER BY record_name;'}],['A','B','C'].map(answer=>[answer,async()=>{const r=await act('sql_answer',{ticket:roomTicket,answer});story(r.correct?'기록의 순서가 바뀌면':'다시 확인해 볼까요','CHAPTER 02 · EVIDENCE LAB',r.correct?[mline('맞아요. C에는 하나의 여분이 있었습니다. 하지만 C는 중간에 작성한 기록이에요.'),mline('이후 참가자가 한 명 늘었습니다. 최종 기록 A는 참가자 11명, 선물 11개. 여분은 없었던 거죠.'),pline('그럼 중간 기록만 보고 누군가 선물을 가져갔을 수도 있겠네요.'),mline('이 사실을 18층 꾸왕이에게 전해 주세요. 사라진 선물의 실마리가 될 겁니다.')]:[mline('선물 수에서 참가자 수를 빼 보세요. 다시 함께 확인할까요?')],r.correct?[['꾸왕이에게 돌아가기',()=>dialog.close()]]:[['수량표 다시 확인',()=>managerAnswer()]],'analysis');}]),'analysis');}
async function interactStation(s,acknowledged=false){held.clear();await refresh();if(s.code==='sql_answer'){await window.CampusApp.greetManager(s,{silent:true});managerConversation();return;}
if(s.code==='sql_memory'&&!state.room1Briefed){info('먼저 영석 매니저님과 대화하세요','오른쪽 영석 매니저님에게 미션 설명을 들은 뒤 서브쿼리 메모리 게임을 시작할 수 있어요.');return;}
if(state.locked[s.code]){info(s.name,state.locked[s.code]+'\n완료 판정은 정책 확정 후 열립니다.',[['작업 화면 보기',()=>lockedScreen(s.code)]]);return;}
if(!practiceLabel.querySelector('input').checked&&((s.code==='sql_memory'&&!state.steps[0].complete)||(s.code!=='sql_memory'&&!state.steps[2].complete))){info(s.name+' · 진행 조건',s.code==='sql_memory'?'18층 꾸왕이에게 먼저 말을 걸어 사건 조사를 시작해 주세요.':'18층 꾸왕이에게 돌아가 빼빼로 타격 챌린지를 마치면 제작실 미션을 진행할 수 있어요.',state.canPractice?[['연습으로 열기 · 메인 진행 반영 안 함',()=>{practiceLabel.querySelector('input').checked=true;dialog.close();return interactStation(s);}]]:[]);return;}
if(room===2&&!acknowledged&&['card_match','coating','topping','wrapping'].includes(s.code)){workshopStory(s.code,()=>interactStation(s,true));return;}
const play=await act('game_start',{game:s.code,ticket:roomTicket,practice:practiceLabel.querySelector('input').checked});activePlay={...play,code:s.code,done:false};gameDialog.querySelector('h2').textContent=s.name;gameDialog.querySelector('.mq-body').replaceChildren();gameDialog.showModal();if(s.code==='sql_memory'||s.code==='card_match')await frameGame(s.code,play);else if(s.code==='coating')coating();else if(s.code==='wrapping')wrapping();else topping();}
async function finish(proof){if(!activePlay||activePlay.done)return;const session=activePlay;session.done=true;try{const result=await act('game_finish',{play:session.play,token:session.token,proof});if(session.practice&&result.success)practiceCompleted.add(session.code);gameDialog.close();info(session.practice?'연습 결과 저장 완료':session.code==='kkuwang_touch'?'STEP 3 완료 · 제작실이 열렸어요':result.success?'성공 · 서버 저장 완료':'다시 도전해 보세요',session.practice?'연습 게임 기록만 저장했어요. 메인 미션은 진행되지 않습니다.':session.code==='kkuwang_touch'?`${result.score}회 톡! 빼빼로가 부서졌어요. 꾸왕이가 반성의 시간을 마쳤습니다.\n옥상 ROOM 02로 이동해 빼빼로 제작을 시작하세요.`:result.success?'진행이 저장되었습니다. 다음 미션 에셋으로 이동하세요.':'이번 판은 실패로 기록되었어요. 이전에 완료한 미션은 유지됩니다.');if(session.code==='coating'&&result.coatingTiming){const timing=result.coatingTiming,recap=document.createElement('p');recap.className='mq-coating-recap';recap.textContent=timing.errorsMs.map((v,i)=>(i+1)+'회 '+(v===null?'놓침':v+'ms')).join(' · ')+'\n평균 '+(timing.averageMs===null?'측정 불가':timing.averageMs.toFixed(1)+'ms')+' / 성공 기준 '+timing.limitMs+'ms 이내'+(timing.inZone?' · 구간 '+timing.inZone.map(v=>v?'성공':'실패').join(' / '):'');dialog.querySelector('.mq-body').prepend(recap);}}catch(e){session.done=false;info('결과 저장 확인 필요',e.message,[['저장 다시 시도',()=>finish(proof)]]);}}
let cleanupGame=()=>{};
gameDialog.addEventListener('close',()=>{cleanupGame();cleanupGame=()=>{};const s=activePlay;activePlay=null;if(s&&!s.done)api({action:'game_interrupt',play:s.play,token:s.token,proof:{}}).catch(()=>{});held.clear();canvas.focus();});
async function frameGame(code,play){const r=await fetch('event-games/'+(code==='sql_memory'?'sql-memory.html':'card.html'),{cache:'no-store'});if(!r.ok)throw new Error('게임 파일을 불러오지 못했어요.');const source=await r.text();if(!gameDialog.open)return;const f=document.createElement('iframe');f.title=code==='sql_memory'?'SQL 순서 기억 게임':'레시피 카드 뒤집기';f.dataset.quest='true';f.srcdoc=source;f.addEventListener('load',()=>f.contentWindow.postMessage({type:'quest:init',challenge:play.challenge},location.origin));gameDialog.querySelector('.mq-body').append(f);const receive=e=>{if(e.source!==f.contentWindow||e.origin!==location.origin||e.data?.type!=='quest:result')return;void finish(e.data.proof);};window.addEventListener('message',receive);cleanupGame=()=>{window.removeEventListener('message',receive);f.remove();};}
async function startTouch(token){
const play=await act('game_start',{game:'kkuwang_touch',ticket:token});dialog.close();activePlay={...play,code:'kkuwang_touch',done:false};gameDialog.querySelector('h2').textContent='꾸왕이 빼빼로 타격 챌린지';
const b=gameDialog.querySelector('.mq-body');b.innerHTML='<section class="mq-hit-game mq-hit-overhead"><div class="mq-hit-stats"><div><small>남은 시간</small><strong class="mq-touch-time">10.0초</strong></div><div><small>부서진 빼빼로</small><strong class="mq-touch-score" aria-live="polite">0회</strong></div></div><div class="mq-hit-arena"><canvas width="880" height="350" aria-label="가운데 꾸왕이가 두 손으로 머리를 감싸고 위에서 내려온 빼빼로가 부서지는 챌린지"></canvas><button type="button" class="mq-hit-target" aria-label="빼빼로로 꾸왕이 때리기" disabled></button><span class="mq-hit-caption">꾸왕이의 반성 시간 · 준비되면 시작하세요</span></div><div class="mq-hit-footer"><p>클릭 / 찌르기 키로 위에서 빼빼로를 톡! 10초를 마치면 ROOM 02 제작실이 열려요.</p><button class="mq-touch-start" type="button">10초 타격 시작</button></div></section>';
gameDialog.showModal();
const c=b.querySelector('canvas'),ctx=c.getContext('2d'),target=b.querySelector('.mq-hit-target'),start=b.querySelector('.mq-touch-start'),counter=b.querySelector('.mq-touch-score'),clock=b.querySelector('.mq-touch-time'),taps=[],strikes=[];
const guide=new Image();guide.src='assets/guide-kkuwang-detective-v1.png';const cover=new Image();cover.src='assets/kkuwang-cover-head-v1.webp';
let origin=null,id,ended=false;const duration=play.challenge.durationMs;
function hit(){if(origin===null||ended)return;const at=performance.now(),t=Math.round(at-origin);if(t>=duration||taps.length>=1000)return;taps.push(t);counter.textContent=taps.length+'회';strikes.push({at,side:taps.length%2?1:-1});if(strikes.length>24)strikes.shift();}
start.onclick=()=>{if(origin!==null)return;origin=performance.now();start.hidden=true;target.disabled=false;target.focus();b.querySelector('.mq-hit-caption').textContent='클릭 / '+(window.CampusKeyboard?.label('poke')||'Z')+' · 위에서 빼빼로 톡!';};target.onclick=hit;
const keydown=e=>{if(gameDialog.open&&(window.CampusKeyboard?.key(e)||e.key.toLowerCase())==='z'){e.preventDefault();e.stopPropagation();if(!e.repeat)hit();}};gameDialog.addEventListener('keydown',keydown);
function biscuit(length){ctx.lineCap='round';ctx.strokeStyle='#dbb47c';ctx.lineWidth=12;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,length);ctx.stroke();ctx.strokeStyle='#603824';ctx.lineWidth=13;ctx.beginPath();ctx.moveTo(0,Math.min(20,length*.2));ctx.lineTo(0,length);ctx.stroke();ctx.strokeStyle='#ad7854';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-3,Math.min(25,length*.3));ctx.lineTo(-3,length-4);ctx.stroke();ctx.fillStyle='#f7c2ce';for(let y=30;y<length-5;y+=17)ctx.fillRect(-4,y,4,3);}
function draw(now){
ctx.clearRect(0,0,880,350);const wall=ctx.createLinearGradient(0,0,0,350);wall.addColorStop(0,'#f3e2ca');wall.addColorStop(.43,'#efcfb7');wall.addColorStop(.43,'#d5b393');wall.addColorStop(1,'#ead4b6');ctx.fillStyle=wall;ctx.fillRect(0,0,880,350);ctx.fillStyle='#805464';ctx.fillRect(0,146,880,7);ctx.strokeStyle='#bb947240';ctx.lineWidth=1;for(let y=175;y<350;y+=45){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(880,y);ctx.stroke();}for(let x=0;x<880;x+=90){ctx.beginPath();ctx.moveTo(440+(x-440)*.7,153);ctx.lineTo(x,350);ctx.stroke();}
ctx.fillStyle='#ac7a85';ctx.beginPath();ctx.ellipse(440,298,170,28,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#eacb98';ctx.lineWidth=3;ctx.stroke();
ctx.fillStyle='#78515b';ctx.fillRect(285,16,310,32);ctx.strokeStyle='#deb773';ctx.strokeRect(290,21,300,22);ctx.fillStyle='#fff1c9';ctx.font='700 12px Georgia';ctx.textAlign='center';ctx.fillText('KKUWANG · A LITTLE REFLECTION',440,37);
const latest=strikes.at(-1),impact=latest?now-latest.at-130:10000,flinch=impact>=0&&impact<280?Math.sin(impact/280*Math.PI):0;
ctx.save();ctx.translate(440+Math.sin(impact*.09)*flinch*4,300);ctx.scale(1+flinch*.04,1-flinch*.055);const img=origin!==null&&cover.complete&&cover.naturalWidth?cover:guide;if(img.complete&&img.naturalWidth)ctx.drawImage(img,-140,-246,280,280);ctx.restore();
for(let i=strikes.length-1;i>=0;i--){const strike=strikes[i],elapsed=now-strike.at;if(elapsed>720){strikes.splice(i,1);continue;}if(elapsed<130){const t=Math.max(0,elapsed/130);ctx.save();ctx.translate(440+strike.side*12*(1-t),-170+180*t);ctx.rotate(strike.side*.12*(1-t));biscuit(90);ctx.restore();}else{const t=(elapsed-130)/590;ctx.save();ctx.globalAlpha=1-t;for(const side of [-1,1]){ctx.save();ctx.translate(440+side*(12+t*110),76+t*18+t*t*155);ctx.rotate(side*(.35+t*3));biscuit(44);ctx.restore();}ctx.fillStyle='#f1c7a0';for(let j=0;j<9;j++){const angle=j*Math.PI*2/9,x=440+Math.cos(angle)*t*120,y=104+Math.sin(angle)*t*60+t*t*130;ctx.save();ctx.translate(x,y);ctx.rotate(t*8+j);ctx.fillStyle=j%3?'#704331':'#eecb8e';ctx.fillRect(-2,-2,4+(j%3),4+(j%2));ctx.restore();}if(t<.3){ctx.strokeStyle='#fff1b6';ctx.lineWidth=3;for(let j=0;j<6;j++){const angle=j*Math.PI/3;ctx.beginPath();ctx.moveTo(440+Math.cos(angle)*14,101+Math.sin(angle)*14);ctx.lineTo(440+Math.cos(angle)*27,101+Math.sin(angle)*27);ctx.stroke();}}ctx.restore();}}
ctx.font='600 12px "Malgun Gothic",sans-serif';ctx.fillStyle='#62474c';ctx.textAlign='center';ctx.fillText(origin===null?'꾸왕이 · 내가 잘못했어…':'꾸왕이 · 반성 중!',440,326);
if(origin!==null&&!ended){const elapsed=now-origin;clock.textContent=(Math.max(0,duration-elapsed)/1000).toFixed(1)+'초';if(elapsed>=duration){ended=true;target.disabled=true;clock.textContent='완료';b.querySelector('.mq-hit-caption').textContent='타격 기록 저장 중…';void finish({taps});}}
id=requestAnimationFrame(draw);
}
id=requestAnimationFrame(draw);cleanupGame=()=>{cancelAnimationFrame(id);gameDialog.removeEventListener('keydown',keydown);strikes.length=0;};
}

function coating(){
const b=gameDialog.querySelector('.mq-body'),challenge=activePlay.challenge,rounds=challenge.rounds,limit=challenge.maxAverageMs,lead=challenge.leadInMs,late=challenge.lateWindowMs;
b.innerHTML='<section class="mq-coating-game"><div class="mq-coating-intro"><span>CHOCOLATE TIMING</span><h3>완벽한 순간에 초콜릿을 멈춰요</h3><p>초콜릿 끝이 분홍색 완벽선에 닿을 때 멈추세요. 세 번 모두 금색 성공 구간 안에서 멈춰야 해요. 완벽선과의 시간 차이도 기록해요.</p></div><div class="mq-coating-summary"><strong class="mq-coating-round">1 / 3회</strong><span>성공 기준 · 3회 평균 <b class="mq-coating-limit"></b></span><strong class="mq-coating-average">평균 —</strong></div><div class="mq-coating-board"><div class="mq-coating-track"><div class="mq-coating-perfect">완벽</div><div class="mq-coating-stick"><div class="mq-coating-cover"></div><div class="mq-coating-zone"></div><div class="mq-coating-line"></div></div></div><div class="mq-coating-labels"><span>코팅 시작</span><strong class="mq-coating-percent">초콜릿 0%</strong><span>전체 코팅</span></div><p class="mq-coating-state" role="status">준비되면 1회차를 시작하세요.</p></div><ol class="mq-coating-results"><li>1회 <strong>—</strong></li><li>2회 <strong>—</strong></li><li>3회 <strong>—</strong></li></ol><div class="mq-coating-actions"><button class="mq-coating-start" type="button">1회차 시작</button><button class="mq-coating-hit" type="button" disabled>지금 멈추기 <kbd>Space</kbd></button></div><p class="mq-coating-note">세 번 모두 성공 구간에 들어와야 해요. 구간 밖이거나 한 번 놓쳤다면 다시 도전해 주세요.</p></section>';
b.querySelector('.mq-coating-limit').textContent=limit+'ms 이내';
const game=b.querySelector('.mq-coating-game'),start=b.querySelector('.mq-coating-start'),hit=b.querySelector('.mq-coating-hit'),message=b.querySelector('.mq-coating-state'),items=[...b.querySelectorAll('.mq-coating-results li')],trials=[],origin=performance.now();let index=0,phase='ready',current=null,id,frozenFill=0;
function setup(){const r=rounds[index],width=limit/r.fillMs*100,zoneLeft=r.zoneLeftPct??Math.max(0,r.targetPct-width),zoneRight=r.zoneRightPct??Math.min(100,r.targetPct+width);game.style.setProperty('--coat-target',r.targetPct+'%');game.style.setProperty('--coat-zone-left',zoneLeft+'%');game.style.setProperty('--coat-zone-width',(zoneRight-zoneLeft)+'%');game.style.setProperty('--coat-fill','0%');b.querySelector('.mq-coating-round').textContent=(index+1)+' / 3회';b.querySelector('.mq-coating-perfect').textContent='완벽';b.querySelector('.mq-coating-percent').textContent='초콜릿 0%';start.textContent=(index+1)+'회차 시작';}
function average(){let sum=0,count=0;trials.forEach((t,i)=>{if(t.stopMs!==null){sum+=Math.abs(t.stopMs-(t.startMs+lead+rounds[i].fillMs*rounds[i].targetPct/100));count++;}});return count?sum/count:null;}
function settle(stopMs){if(phase!=='running')return;const r=rounds[index],ideal=current.startMs+lead+r.fillMs*r.targetPct/100,signed=stopMs===null?null:stopMs-ideal,error=signed===null?null:Math.abs(signed),fill=stopMs===null?null:(stopMs-current.startMs-lead)/r.fillMs*100,inZone=fill!==null&&fill>=(r.zoneLeftPct??-Infinity)&&fill<=(r.zoneRightPct??Infinity);trials.push({...current,stopMs});phase='feedback';hit.disabled=true;items[index].className=error===null?'miss':error<=limit&&inZone?'good':'late';items[index].querySelector('strong').textContent=error===null?'놓침':error+'ms';message.textContent=error===null?'코팅이 끝났어요. 이번 회차는 기록하지 못했어요.':error===0?'완벽! 0ms 오차예요.':error+'ms '+(signed<0?'빠르게':'늦게')+' 멈췄어요.'+(inZone?' · 성공 구간!':' · 성공 구간 밖!');const avg=average();b.querySelector('.mq-coating-average').textContent=trials.some(t=>t.stopMs===null)?'평균 · 놓침 포함':'평균 '+avg.toFixed(1)+'ms';index++;if(index===rounds.length){phase='done';start.hidden=true;message.textContent+=' 결과를 저장하고 있어요.';const all=trials.every((t,i)=>{const r=rounds[i],f=t.stopMs===null?null:(t.stopMs-t.startMs-lead)/r.fillMs*100;return f!==null&&f>=(r.zoneLeftPct??-Infinity)&&f<=(r.zoneRightPct??Infinity);}),passed=all&&avg<=limit;void finish({success:passed,trials});return;}start.hidden=false;start.textContent=(index+1)+'회차 시작';}
function press(){if(phase!=='running')return;const at=Math.round(performance.now()-origin),r=rounds[index];if(at>current.startMs+lead+r.fillMs+late){settle(null);return;}frozenFill=Math.max(0,Math.min(100,(at-current.startMs-lead)/r.fillMs*100));game.style.setProperty('--coat-fill',frozenFill+'%');settle(at);}
start.onclick=()=>{if(phase==='running'||phase==='done')return;setup();current={startMs:Math.round(performance.now()-origin)};phase='running';start.hidden=true;hit.disabled=false;hit.focus();message.textContent='준비… 초콜릿이 올라오면 완벽선을 보고 멈추세요.';};
hit.onpointerdown=e=>{if(e.button===0){e.preventDefault();press();}};hit.onclick=e=>{if(e.detail===0)press();};
const onKey=e=>{if(e.code==='Space'||e.key===' '){e.preventDefault();e.stopPropagation();if(!e.repeat)press();}};gameDialog.addEventListener('keydown',onKey);
function draw(){if(phase==='running'){const elapsed=performance.now()-origin-current.startMs,r=rounds[index],fill=Math.max(0,Math.min(100,(elapsed-lead)/r.fillMs*100));game.style.setProperty('--coat-fill',fill+'%');b.querySelector('.mq-coating-percent').textContent='초콜릿 '+Math.round(fill)+'%';if(elapsed>=lead)message.textContent='초콜릿 끝이 완벽선에 닿는 순간 멈추세요!';if(elapsed>=lead+r.fillMs+late){frozenFill=100;settle(null);}}id=requestAnimationFrame(draw);}
setup();id=requestAnimationFrame(draw);cleanupGame=()=>{cancelAnimationFrame(id);gameDialog.removeEventListener('keydown',onKey);};
}

function topping(){if(activePlay.challenge.rulesVersion>=3){gameDialog.classList.add('mq-topping-expanded');const cleanup=window.CampusToppingOrder.start(gameDialog.querySelector('.mq-body'),activePlay.challenge,finish);cleanupGame=()=>{cleanup();gameDialog.classList.remove('mq-topping-expanded');};return;}toppingLegacy();}
function toppingLegacy(){const b=gameDialog.querySelector('.mq-body'),challenge=activePlay.challenge,duration=challenge.durationMs||30000,goal=challenge.minCatch||12,radius=challenge.catchRadius||82;b.innerHTML='<p>위에서 뿌려지는 초콜릿 칩·스프링클·별사탕을 받아 빼빼로를 꾸미세요. 좌우 방향키 또는 드래그로 움직입니다.</p><canvas class="mq-topping-canvas" width="800" height="340" tabindex="0"></canvas><div class="mq-stats" aria-live="polite"></div>';const c=b.querySelector('canvas'),ctx=c.getContext('2d'),caught=[],origin=performance.now();let x=400,id;const seed=challenge.seed,px=i=>60+((seed*(i+17)*97)%680);c.onpointermove=e=>{x=Math.max(85,Math.min(715,(e.clientX-c.getBoundingClientRect().left)/c.clientWidth*800));};c.onkeydown=e=>{if(e.key==='ArrowLeft')x=Math.max(85,x-30);if(e.key==='ArrowRight')x=Math.min(715,x+30);e.preventDefault();};c.focus();function decor(kind,dx,dy,scale=1){ctx.save();ctx.translate(dx,dy);ctx.scale(scale,scale);ctx.rotate(kind);if(kind%3===0){ctx.fillStyle='#5c352b';ctx.beginPath();ctx.moveTo(0,-11);ctx.lineTo(10,8);ctx.lineTo(-10,8);ctx.closePath();ctx.fill();}else if(kind%3===1){ctx.fillStyle='#ce789a';for(let j=0;j<3;j++)ctx.fillRect(-9+j*7,-5+j%2*5,4,12);}else{ctx.fillStyle='#fff1d0';ctx.beginPath();for(let j=0;j<10;j++){const a=j*Math.PI/5,r=j%2?5:11;j?ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r):ctx.moveTo(Math.cos(a)*r,Math.sin(a)*r);}ctx.closePath();ctx.fill();}ctx.restore();}function frame(){const t=(performance.now()-origin)/1000;ctx.clearRect(0,0,800,340);ctx.fillStyle='#a66c83';ctx.fillRect(35,6,730,4);ctx.fillStyle='#d5a16d';ctx.fillRect(x-80,292,160,20);ctx.fillStyle='#603b2e';ctx.fillRect(x-65,292,145,20);ctx.fillStyle='#eac4a0';ctx.fillRect(x-80,298,15,3);for(const hit of caught){const offset=Math.max(-61,Math.min(69,px(hit.id)-hit.x));decor(hit.id, x+offset,298+(hit.id%2)*6,.3);}for(let i=0;i<40;i++){const y=(t-i*.7)*125;if(y<0||y>330||caught.some(h=>h.id===i))continue;decor(i,px(i),y);if(y>=282&&y<=314&&Math.abs(px(i)-x)<radius)caught.push({id:i,at:Math.round(t*1000),x});}b.querySelector('.mq-stats').textContent=`남은 시간 ${Math.max(0,Math.ceil(duration/1000-t))}초 · 데코 ${caught.length}/${goal}개`;if(t>=duration/1000){void finish({success:true,caught});return;}id=requestAnimationFrame(frame);}frame();cleanupGame=()=>cancelAnimationFrame(id);}
function wrapping(){const b=gameDialog.querySelector('.mq-body'),session=activePlay,duration=session.challenge.durationMs,sequence=session.challenge.sequence;b.innerHTML='<div class="mq-wrap"><p>정성껏 꾸민 빼빼로를 선물로 포장해요.</p><div class="mq-wrap-stage"><div class="mq-wrap-paper"><div class="mq-wrap-stick"></div><div class="mq-wrap-flap left"></div><div class="mq-wrap-flap right"></div><div class="mq-wrap-ribbon"></div><div class="mq-wrap-bow">୨୧</div></div></div><p class="mq-wrap-label" aria-live="polite">포장할 준비가 되었어요.</p><button type="button">포장 시작</button></div>';const start=b.querySelector('button'),label=b.querySelector('.mq-wrap-label'),paper=b.querySelector('.mq-wrap-paper');let id;start.onclick=()=>{start.disabled=true;const origin=performance.now();function frame(){const elapsed=performance.now()-origin,t=Math.min(1,elapsed/duration),step=Math.min(sequence.length-1,Math.floor(t*sequence.length));label.textContent=sequence[step];paper.dataset.step=step;paper.style.setProperty('--wrap-progress',t);if(elapsed>=duration){label.textContent='포장 완료 · 서버에 저장하는 중…';void finish({success:true,animationMs:duration,sequence});return;}id=requestAnimationFrame(frame);}frame();};cleanupGame=()=>cancelAnimationFrame(id);}

function lockedScreen(code){dialog.close();held.clear();gameDialog.querySelector('h2').textContent=code==='typing'?'레시피 타이핑 · 완료 잠금':'선물 포장 · 완료 잠금';const b=gameDialog.querySelector('.mq-body');b.innerHTML='<p class="mq-note">성공 기준 미정 · 이 화면에서는 진행이 저장되지 않습니다.</p>';if(code==='typing'){const f=document.createElement('iframe');f.title='타이핑 게임 준비 화면';f.src='event-games/typing.html';f.style.pointerEvents='none';f.setAttribute('tabindex','-1');b.append(f);}else{const img=document.createElement('img');img.src='assets/seasonal/pepero/reference/pedestal.png';img.alt='리본과 빼빼로가 담긴 선물 포장대';img.style.cssText='display:block;width:240px;max-width:90%;margin:20px auto';b.append(img);const p=document.createElement('p');p.textContent='포장지 선택 → 빼빼로 담기 → 리본 묶기\n세부 규칙 확정 후 조작과 완료 판정을 연결합니다.';b.append(p);}gameDialog.showModal();}
function roomProgress(){if(room===1)return [{code:'intro',name:'영석 매니저 대화',done:!!state?.room1Briefed},{code:'sql_memory',name:'서브쿼리 메모리',done:!!state?.games.sql_memory||(practiceLabel.querySelector('input').checked&&practiceCompleted.has('sql_memory'))},{code:'sql_answer',name:'수량표 분석',done:!!state?.steps[1].complete}];return stationList().map(s=>({code:s.code,name:s.name.slice(5),done:!!state?.games[s.code]||(practiceLabel.querySelector('input').checked&&practiceCompleted.has(s.code))}));}
function roomObjective(){const progress=roomProgress(),current=progress.find(s=>!s.done);if(!current)return {code:'exit',name:'완료 · 옥상으로 나가기',interactionPoint:missionMap.exit.interactionPoint};return {...stationList().find(s=>s.code===(current.code==='intro'?'sql_answer':current.code)),name:current.name};}
function updateRoomJourney(){const progress=roomProgress(),next=progress.findIndex(p=>!p.done),key=JSON.stringify(progress)+practiceLabel.querySelector('input').checked;if(roomSteps.dataset.state!==key){roomSteps.dataset.state=key;roomSteps.querySelector('ol').replaceChildren(...progress.map((s,i)=>{const li=document.createElement('li');li.dataset.code=s.code;li.className=s.done?'done':i===next?'current':'';li.innerHTML='<b></b><span></span>';li.querySelector('b').textContent=s.done?'✓':String(i+1).padStart(2,'0');li.querySelector('span').textContent=s.name;return li;}));roomSteps.querySelector('.mq-room-count').textContent=progress.filter(p=>p.done).length+' / '+progress.length;roomSteps.querySelector('.mq-room-mode').textContent=practiceLabel.querySelector('input').checked?'연습 진행':room===1?'증거 분석':'제작 순서';}roomNext.textContent='NEXT  ·  '+(next<0?'작업 완료! 옥상 출입구로 이동하세요.':progress[next].name);}
const questReducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function drawMissionMarker(ctx,x,y,t){const bounce=questReducedMotion.matches?0:Math.sin(t/230)*3;ctx.save();ctx.translate(x,y-18+bounce);ctx.shadowColor='#ffdc7a';ctx.shadowBlur=9;ctx.fillStyle='#fff0ad';ctx.strokeStyle='#82452b';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(0,-48);ctx.lineTo(4,-42);ctx.lineTo(0,-36);ctx.lineTo(-4,-42);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;const gold=ctx.createLinearGradient(0,-31,0,0);gold.addColorStop(0,'#fff1a6');gold.addColorStop(.5,'#ffd364');gold.addColorStop(1,'#e5a13d');ctx.fillStyle=gold;ctx.beginPath();ctx.moveTo(-9,-30);ctx.lineTo(9,-30);ctx.lineTo(9,-18);ctx.lineTo(15,-18);ctx.lineTo(0,-2);ctx.lineTo(-15,-18);ctx.lineTo(-9,-18);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#fff8d9';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-6,-26);ctx.lineTo(6,-26);ctx.stroke();ctx.strokeStyle='#bc7630';ctx.beginPath();ctx.moveTo(-8,-15);ctx.lineTo(0,-6);ctx.lineTo(8,-15);ctx.stroke();ctx.fillStyle='#f9dd9e';for(const [dx,dy] of [[-20,-23],[19,-34]]){ctx.beginPath();ctx.moveTo(dx,dy-3);ctx.lineTo(dx+2,dy);ctx.lineTo(dx,dy+3);ctx.lineTo(dx-2,dy);ctx.closePath();ctx.fill();}ctx.restore();}
let lastTime=0;
function roomDraw(t){requestAnimationFrame(roomDraw);if(room===1&&held.has('z'))pokeRoom().catch(error=>window.CampusApp.toast(error.message));roomPokeButton.hidden=room!==1;const dt=Math.min(.04,(t-lastTime)/1000||0);lastTime=t;if(!room||!interior.open||!missionRenderer)return;
const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio,2);if(!rect.width||!rect.height)return;if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);}
syncRoomInventory();updateRoomJourney();const objective=roomObjective();const blocked=dialog.open||gameDialog.open||window.CampusFreeze?.blocking;if(blocked)held.clear();window.CampusApp.presence.setInput([...held].filter(key=>key!=='z'));
const blend=1-Math.exp(-dt*18);actor.x+=(actor.targetX-actor.x)*blend;actor.y+=(actor.targetY-actor.y)*blend;actor.walkTime=actor.moving?(actor.walkTime||0)+dt:0;
const view=missionMap.viewBounds,zoom=Math.min(rect.width/view.w,rect.height/view.h),camera={zoom,x:(rect.width-view.w*zoom)/2-view.x*zoom,y:(rect.height-view.h*zoom)/2-view.y*zoom};g.setTransform(dpr,0,0,dpr,0,0);g.fillStyle=room===1?'#c1c9c4':'#dbc0b4';g.fillRect(0,0,rect.width,rect.height);g.save();g.translate(camera.x,camera.y);g.scale(zoom,zoom);
missionRenderer.draw(g,{camera,actors:[actor],t,nearby:null,viewportWidth:rect.width,viewportHeight:rect.height,floorOverlay:()=>{const P=missionRenderer.projection;for(const st of stationList()){const at=st.interactionPoint,q=P.project(at[0],at[1]);g.fillStyle=state?.games[st.code]?'#47776d':'#956776';g.beginPath();g.ellipse(q.x,q.y,17,6,0,0,Math.PI*2);g.fill();g.fillStyle='#fff1d7';g.font='700 10px sans-serif';g.textAlign='center';g.fillText(st.code==='sql_answer'?'대화':String(st.name.slice(0,2)),q.x,q.y+3);}}});
const P=missionRenderer.projection;g.font='600 11px "Malgun Gothic",sans-serif';g.textAlign='center';for(const st of stationList().filter(s=>s.type!=='mission-manager')){const q=P.project(st.x+st.w/2,st.y+st.h,room===2?(st.artHeight||64)+17:85);g.fillStyle='#fff4df';const w=g.measureText(st.name).width+14;g.fillRect(q.x-w/2,q.y-10,w,19);g.fillStyle='#623e48';g.fillText(st.name,q.x,q.y+3);}const exit=P.project(...missionMap.exit.interactionPoint);g.fillStyle='#fff0c7';g.fillRect(exit.x-40,exit.y-5,80,20);g.fillStyle='#714753';g.fillText('옥상 출입구',exit.x,exit.y+9);
if(!blocked&&objective){const q=P.project(...objective.interactionPoint);drawMissionMarker(g,q.x,q.y,t);}g.restore();
$('mainQuestRoomHint').textContent=nearStation?`${window.CampusKeyboard?.label('interact')||'E'} · ${nearStation.name}`:room===1?(!state?.room1Briefed?'먼저 영석 매니저님과 대화하세요':state?.games.sql_memory?'영석 매니저님에게 수량표를 제출하세요':'왼쪽 서브쿼리 메모리 분석기에 도전하세요'):'재료 준비 → 초콜릿 코팅 → 토핑 데코 → 선물 포장';$('mainQuestInteract').disabled=!nearStation;}
requestAnimationFrame(roomDraw);
function goal(){if(!state||state.completed)return null;return [{...mainGuide,name:'꾸왕이 · 사건 조사 시작'},{...portals[0]},{...mainGuide,name:'꾸왕이 · 사건의 진실'},{...portals[1]},{...mainGuide,name:'꾸왕이 · 선물 전달'}][state.stage-1];}
function questArrowPlacement(point,width,height){
const inside=point.x>=0&&point.x<=width&&point.y>=0&&point.y<=height;
if(inside)return {mode:'target',x:Math.max(80,Math.min(width-80,point.x)),y:Math.max(115,Math.min(height-65,point.y-32)),angle:0};
const cx=width/2,cy=height/2,dx=point.x-cx,dy=point.y-cy,mx=Math.min(105,width*.2),my=Math.min(115,height*.22),halfX=Math.max(1,cx-mx),halfY=Math.max(1,cy-my),factor=Math.min(dx?halfX/Math.abs(dx):Infinity,dy?halfY/Math.abs(dy):Infinity);
return {mode:'edge',x:cx+dx*factor,y:cy+dy*factor,angle:Math.atan2(dy,dx)*180/Math.PI-90};
}
window.CampusQuestNavigation={place:questArrowPlacement};
window.CampusStory={get blocking(){return dialog.open||interior.open||gameDialog.open;},get activeObjective(){return room?roomObjective()?.code:null;},get missionActive(){return room>0;},applyMissionState,get missionActor(){return room?{...actor}:null;},get state(){return state;},get restored(){return !!state?.completed;},handles(o){return o.action==='recipe-note'||o.action==='mission-manager'||o.id==='class3-4-noticeboard'||o.action==='story';},open(o){if(o.action==='recipe-note'){run(recipeNote);return;}if(o.action==='mission-manager'){info(o.name,o.copy||'반가워요. 오늘도 즐거운 캠퍼스 생활 되세요!');return;}run(()=>o.id==='class3-4-noticeboard'?Promise.resolve(info('이벤트 게시판','사라진 선물을 찾아 주세요. 18층 꾸왕이에게 말을 걸면 메인 미션이 시작됩니다.\n기간: 11월 9일 08:30 ~ 11월 11일 22:00',[['일반 게시판',()=>{dialog.close();window.CampusApp.openRegularBoard();}]])):investigate());},guide(){run(async()=>{await refresh();if(state.completed){await recipeGuide();return;}if(state.stage===1){await investigate();return;}if(state.stage===3){await confession();return;}if(state.stage===5){story('마지막 한 개의 선물','CHAPTER 05 · A GIFT RESTORED',[pline('완성했어. 직접 코팅하고 토핑을 올려서 포장한 빼빼로야.'),kline('나 때문에 시작한 일인데, 끝까지 도와줬구나… 이 선물로 모두에게 하나씩 나눠 줄 수 있겠어!',{emotion:'happy'}),kline('준비가 됐다면 선물을 건네 줘. 이번에는 마지막 수량표까지 꼭 확인할게!')],[['선물 전달',async()=>{await act('deliver',{ticket:await ticket('final-guide')});story('사라진 11번째 빼빼로 · 해결','EPILOGUE · SWEETER TOGETHER',[kline('열한 명에게 열한 개. 이제 누구의 선물도 빠지지 않았어!',{emotion:'happy'}),pline('다음부터는 중간 기록만 보고 먹으면 안 돼.'),kline('약속할게! 사라진 선물도, 내 실수도 함께 해결해 줘서 고마워. 오늘의 탐정은 바로 너야!',{emotion:'happy'})],[['사건 해결 · 캠퍼스로',()=>dialog.close()]]);}]]);}else story('안내가이드 꾸왕이','MAIN QUEST',[kline(guidance())],state.stage>=4?[['빼빼로 타격 다시하기',()=>confession()]]:[]);});},paint(o,h,base){if(o.type?.startsWith('mission-'))return window.CampusMissionRooms.paint(o,h,base);if(o.type!=='story-evidence')return false;h.box(o.x,o.y,o.w,o.h,base+24,8,'#ffebcd','#a77750','#77513e');for(let i=0;i<3;i++)h.plane(o.x+25+i*38,o.y+25,30,22,base+33,'#fff8ea','#b98262');return true;},updateClassroom(){},update({project,width,height,blocked}){const app=window.CampusApp;if(!app)return;exteriorBlocked=blocked;for(const p of portals){const q=project(p.x,p.y);p.button.hidden=app.floor!==p.floor||blocked||room>0||Math.hypot(app.player.x-p.x,app.player.y-p.y)>85;p.button.style.left=q.x+'px';p.button.style.top=q.y+'px';p.button.querySelector('strong').textContent=(window.CampusKeyboard?.label('interact')||'E')+' · '+p.name+' 입장';}let target=goal();arrow.hidden=blocked||!target||room>0;if(!arrow.hidden){if(target.floor!==app.floor){const stair=app.data.objects.find(o=>o.toFloor===target.floor);if(stair)target={x:stair.interactionPoint?.[0]??stair.x+stair.w/2,y:stair.interactionPoint?.[1]??stair.y+stair.h/2,name:target.floor==='rooftop'?'옥상으로 이동':'18층으로 이동'};else{arrow.hidden=true;return;}}const a=project(target.x,target.y),placement=questArrowPlacement(a,width,height);if(placement.mode==='edge'&&placement.x>width-285&&placement.y<500){placement.x=Math.max(95,width-385);placement.angle=Math.atan2(a.y-placement.y,a.x-placement.x)*180/Math.PI-90;}arrow.dataset.mode=placement.mode;arrow.classList.toggle('is-offscreen',placement.mode==='edge');arrow.style.left=placement.x+'px';arrow.style.top=placement.y+'px';arrow.style.setProperty('--quest-bearing',placement.angle+'deg');arrow.querySelector('.mq-arrow-tag').textContent=placement.mode==='edge'?'GO TO':'MAIN QUEST';arrow.querySelector('.mq-arrow-label').textContent=target.name;}}};
window.addEventListener('campus:learning-result',()=>run(refresh));window.addEventListener('focus',()=>{if(Date.now()-lastRefresh>5000)run(refresh);});window.addEventListener('campus:freeze',()=>{if(!window.CampusFreeze?.blocking)return;gameDialog.close();dialog.close();held.clear();window.CampusApp?.presence.setInput([]);});
const initialize=()=>run(async()=>{await refresh();const r=await act('notice');if(r.show_notice)story('사라진 11번째 빼빼로','PROLOGUE · 11.11',[kline('모두를 위한 선물을 준비하던 캠퍼스에 작은 사건이 일어났어.'),kline('열한 번째 빼빼로 선물이 사라졌거든! 18층 게시판 앞에서 기다릴게. 직접 말을 걸어 주면 조사를 시작하자.')],[['캠퍼스에서 시작하기',()=>dialog.close()]]);});window.addEventListener('campus:ready',initialize,{once:true});window.addEventListener('campus:freeze',()=>{if(!window.CampusFreeze?.blocking&&!state)initialize();});
})();
